  weight: ["600", "700"],
})

const bodyFont = Plus_Jakarta_Sans({
  subsets: ["latin"],
  weight: ["400", "500", "600", "700"],
})

const getErrorMessage = (value: unknown) => {
  if (typeof value === "string") {
    return value
  }
  if (value && typeof value === "object") {
    if ("message" in value && typeof value.message === "string") {
      return value.message
    }
    if ("error" in value && typeof value.error === "string") {
      return value.error
    }
  }
  return "Could not create your account. Try again."
}

export default function SignUpPage() {
  const router = useRouter()
  const { data: session, isPending: sessionLoading } = authClient.useSession()

  const [name, setName] = useState("")
  const [email, setEmail] = useState("")
  const [password, setPassword] = useState("")
  const [confirmPassword, setConfirmPassword] = useState("")
  const [submitting, setSubmitting] = useState(false)
  const [errorMessage, setErrorMessage] = useState("")

useEffect(() => {
  if (!sessionLoading && session?.user) {
    router.replace("/onboarding/tokens")
  }
}, [router, session, sessionLoading])

const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
  event.preventDefault()
  setErrorMessage("")

  if (password !== confirmPassword) {
    setErrorMessage("Passwords do not match.")
    return
  }

  if (password.length < 8) {
    setErrorMessage("Password must be at least 8 characters.")
    return
  }

  setSubmitting(true)

  const { error } = await authClient.signUp.email({
    name: name.trim(),
    email: email.trim(),
    password,
    callbackURL: "/onboarding/tokens",
  })

  setSubmitting(false)

  if (error) {
    setErrorMessage(getErrorMessage(error))
    return
  }

  router.push("/onboarding/tokens")
}

return (
  <main
    className={`${bodyFont.className} relative min-h-screen overflow-hidden bg-[radial-gradient(circle_at_15%_15%,#fdf2d8_0%,transparent_42%),radial-gradient(circle_at_88%_8%,#dbeafe_0%,transparent_35%),linear-gradient(165deg,#f8fafc_0%,#fff7ed_45%,#f8fafc_100%)]`}
  >
    <div className="pointer-events-none absolute inset-0 [background-image:linear-gradient(rgba(15,23,42,0.04)_1px,transparent_1px),linear-gradient(90deg,rgba(15,23,42,0.04)_1px,transparent_1px)] [background-size:44px_44px]" />

    <section className="relative mx-auto grid min-h-screen w-full max-w-6xl gap-10 px-6 py-10 lg:grid-cols-[1.1fr_0.9fr] lg:items-center lg:px-10">

import { relations } from "drizzle-orm";
import { account } from "./account";
import { session } from "./session";
import { user } from "./user";

export const userRelations = relations(user, ({ many }) => ({
  accounts: many(account),
  sessions: many(session),
}));

export const accountRelations = relations(account, ({ one }) => ({
  user: one(user, {
    fields: [account.userId],
    references: [user.id],
  }),
}));

export const sessionRelations = relations(session, ({ one }) => ({
  user: one(user, {
    fields: [session.userId],
    references: [user.id],
  }),
}));

const ONBOARDING_STORAGE_KEY = "argus-onboarding-selections-v2"

const routeStepPosition: Record<OnboardingRouteStep, number> = {
  tokens: 1,
  projects: 2,
  mrs: 3,
}

const resolveGitLabInstance = (instance: string, customValue: string) => {
  const value = (instance === "custom" ? customValue : instance).trim()
  if (!value) {
    throw new Error("Please select or enter a GitLab instance.")
  }
  return value.replace(/\/+$/, "")
}

const readPersistedState = (): Partial<OnboardingSessionState> => {
  const raw = window.sessionStorage.getItem(ONBOARDING_STORAGE_KEY)
  if (!raw) {
    return {}
  }

  try {
    const parsed = JSON.parse(raw) as Partial<OnboardingSessionState>
    return parsed && typeof parsed === "object" ? parsed : {}
  } catch {
    return {}
  }
}

const isNonEmptyString = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0

const buildProjectsCacheKey = (instanceUrl: string, token: string) =>
  `${instanceUrl}::${token.trim()}`

export function OnboardingFlow({ routeStep }: { routeStep: OnboardingRouteStep }) {
  const router = useRouter()
  const currentStep = routeStepPosition[routeStep]
  const startedEventTracked = useRef(false)
  const completionEventTracked = useRef(false)
  const projectSelectionHandlerRef = useRef<
    ((projectId: string) => Promise<void>) | null
  >(null)
  const projectsCacheRef = useRef<ProjectsCacheEntry | null>(null)
  const projectsRequestRef = useRef<ProjectsRequestEntry | null>(null)

  const [isHydrated, setIsHydrated] = useState(false)

const [gitlabInstance, setGitlabInstance] = useState(INSTANCE_PRESETS[0])
const [customInstance, setCustomInstance] = useState("https://")
const [token, setToken] = useState("")
const [projects, setProjects] = useState<Project[]>([])
const [projectsError, setProjectsError] = useState("")
const [selectedProjectId, setSelectedProjectId] = useState("")
const [projectSearchQuery, setProjectSearchQuery] = useState("")

const [mergeRequests, setMergeRequests] = useState<MergeRequest[]>([])
const [mergeRequestsError, setMergeRequestsError] = useState("")
const [selectedMergeRequestId, setSelectedMergeRequestId] = useState("")
const [actionBusy, setActionBusy] = useState(false)
const [tokenTestBusy, setTokenTestBusy] = useState(false)
const [tokenTestFeedback, setTokenTestFeedback] =
  useState<TokenTestFeedback | null>(null)

const selectedProject = projects.find((project) => project.id === selectedProjectId)
const selectedMergeRequest = mergeRequests.find((mr) => mr.id === selectedMergeRequestId)

const canLoadProjects = useMemo(
  () =>
    token.trim().length > 0 &&
    (gitlabInstance === "custom"
      ? customInstance.trim().length > 0
      : gitlabInstance.trim().length > 0),
  [token, gitlabInstance, customInstance],
)
const normalizedProjectSearchQuery = useMemo(
  () => projectSearchQuery.trim().toLowerCase(),
  [projectSearchQuery],
)

const filteredProjects = useMemo(() => {
  if (!normalizedProjectSearchQuery) {
    return projects
  }

  return projects.filter((project) => {
    const name = project.name.toLowerCase()
    const path = project.path.toLowerCase()
    return (
      name.includes(normalizedProjectSearchQuery) ||
      path.includes(normalizedProjectSearchQuery)
    )
  })
}, [projects, normalizedProjectSearchQuery])
const recentProjects = useMemo(() => filteredProjects.slice(0, 10), [filteredProjects])
const resolvedGitLabInstance = useMemo(() => {
  if (!token.trim()) {
    return ""
  }

  try {
    return resolveGitLabInstance(gitlabInstance, customInstance)
  } catch {
    return ""
  }
}, [token, gitlabInstance, customInstance])
const projectsCacheKey = useMemo(() => {
  if (!token.trim()) {
    return ""
  }

  try {
    const normalizedInstance = resolveGitLabInstance(gitlabInstance, customInstance)
    return buildProjectsCacheKey(normalizedInstance, token)
  } catch {
    return ""
  }
}, [token, gitlabInstance, customInstance])

const trackEvent = async (
  event:
    | "onboarding_started"
    | "onboarding_token_validated"
    | "onboarding_projects_selected"
    | "onboarding_completed",
  metadata?: OnboardingEventMetadata,
) => {
  await fetch("/api/onboarding/track", {
    method: "POST",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify({ event, metadata }),
  }).catch(() => null)
}

const getErrorMessage = (value: unknown) => {
  if (typeof value === "string") {
    return value
  }
  if (value && typeof value === "object" && "error" in value) {
    return String((value as { error?: string }).error)
  }
  return "Something went wrong."
}

const callGitLab = async (
  action: "projects" | "merge-requests",
  projectId?: string,
) => {
  const normalizedInstance = resolveGitLabInstance(gitlabInstance, customInstance)
  const response = await fetch("/api/gitlab", {
    method: "POST",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify({
      action,
      instanceUrl: normalizedInstance,
      token,
      ...(projectId ? { projectId } : {}),
    }),
  })

  const payload = await response.json()
  if (!response.ok) {
    throw new Error(getErrorMessage(payload))
  }

  if (!Array.isArray(payload.data)) {
    throw new Error("Unexpected response from server.")
  }

  return payload.data
}

const applyLoadedProjects = (data: Project[]) => {
  setProjects(data)
  setSelectedProjectId("")
  setMergeRequests([])
  setSelectedMergeRequestId("")
}

const fetchProjects = async ({ force = false }: { force?: boolean } = {}) => {
  if (!projectsCacheKey) {
    throw new Error("Personal access token is required.")
  }

  const pendingRequest = projectsRequestRef.current
  if (pendingRequest && pendingRequest.key === projectsCacheKey) {
    return pendingRequest.promise
  }

  const cachedEntry = projectsCacheRef.current
  if (!force && cachedEntry && cachedEntry.key === projectsCacheKey) {
    return cachedEntry.projects
  }

  const request = (async () => {
    const data = (await callGitLab("projects")) as Project[]
    projectsCacheRef.current = { key: projectsCacheKey, projects: data }
    return data
  })()

  projectsRequestRef.current = { key: projectsCacheKey, promise: request }

  try {
    return await request
  } finally {
    if (projectsRequestRef.current?.promise === request) {
      projectsRequestRef.current = null
    }
  }
}

const preloadProjectsForContinue = () => {
  if (!canLoadProjects || actionBusy || tokenTestBusy) {
    return
  }

  router.prefetch("/onboarding/projects")
  void fetchProjects().catch(() => null)
}

const loadProjects = async ({ force = false }: { force?: boolean } = {}) => {
  setActionBusy(true)
  setProjectsError("")
  setMergeRequestsError("")
  setTokenTestFeedback(null)

  try {
    const data = await fetchProjects({ force })
    applyLoadedProjects(data)
    await trackEvent("onboarding_token_validated", {
      instanceUrl: resolveGitLabInstance(gitlabInstance, customInstance),
    })
    return true
  } catch (error) {
    setProjectsError(getErrorMessage(error))
    return false
  } finally {
    setActionBusy(false)
  }
}

const testToken = async () => {
  setTokenTestBusy(true)
  setProjectsError("")
  setMergeRequestsError("")
  setTokenTestFeedback(null)

  try {
    const data = await fetchProjects()
    applyLoadedProjects(data)
    const countLabel = data.length === 1 ? "1 project" : `${data.length} projects`
    setTokenTestFeedback({
      kind: "success",
      message: `Token is valid. Found ${countLabel}.`,
    })
  } catch (error) {
    setTokenTestFeedback({
      kind: "error",
      message: getErrorMessage(error),
    })
  } finally {
    setTokenTestBusy(false)
  }
}

const loadMergeRequests = async (projectId: string) => {
  setActionBusy(true)
  setMergeRequestsError("")

  try {
    const data = (await callGitLab("merge-requests", projectId)) as MergeRequest[]
    setMergeRequests(data)
    setSelectedMergeRequestId("")
    await trackEvent("onboarding_projects_selected", {
      selectedProjectCount: projects.length,
      projectId,
    })
    router.push("/onboarding/mrs")
  } catch (error) {
    setMergeRequestsError(getErrorMessage(error))
  } finally {
    setActionBusy(false)
  }
}

const handleTokenSubmit = async (event: FormEvent<HTMLFormElement>) => {
  event.preventDefault()
  const success = await loadProjects()
  if (success) {
    router.push("/onboarding/projects")
  }
}

const handleProjectSelection = async (projectId: string) => {
  setSelectedProjectId(projectId)
  await loadMergeRequests(projectId)
}
projectSelectionHandlerRef.current = handleProjectSelection

const handleMergeRequestSelection = (mrId: string) => {
  setSelectedMergeRequestId(mrId)
  if (!completionEventTracked.current) {
    completionEventTracked.current = true
    void trackEvent("onboarding_completed", {
      projectId: selectedProjectId,
      mergeRequestId: mrId,
    })
  }
}

useEffect(() => {
  const persisted = readPersistedState()
  if (isNonEmptyString(persisted.gitlabInstance)) {
    setGitlabInstance(persisted.gitlabInstance)
  }
  if (isNonEmptyString(persisted.customInstance)) {
    setCustomInstance(persisted.customInstance)
  }

  if (isNonEmptyString(persisted.token)) {
    setToken(persisted.token)
  }
  if (Array.isArray(persisted.projects)) {
    const persistedProjects = persisted.projects as Project[]
    setProjects(persistedProjects)
    if (
      isNonEmptyString(persisted.token) &&
      (isNonEmptyString(persisted.gitlabInstance) ||
        isNonEmptyString(persisted.customInstance))
    ) {
      try {
        const persistedInstance = isNonEmptyString(persisted.gitlabInstance)
          ? persisted.gitlabInstance
          : INSTANCE_PRESETS[0]
        const persistedCustomInstance = isNonEmptyString(persisted.customInstance)
          ? persisted.customInstance
          : ""
        const normalizedInstance = resolveGitLabInstance(
          persistedInstance,
          persistedCustomInstance,
        )
        projectsCacheRef.current = {
          key: buildProjectsCacheKey(normalizedInstance, persisted.token),
          projects: persistedProjects,
        }
      } catch {
        projectsCacheRef.current = null
      }
    }
  }
  if (isNonEmptyString(persisted.selectedProjectId)) {
    setSelectedProjectId(persisted.selectedProjectId)
  }
  if (Array.isArray(persisted.mergeRequests)) {
    setMergeRequests(persisted.mergeRequests as MergeRequest[])
  }
  if (isNonEmptyString(persisted.selectedMergeRequestId)) {
    setSelectedMergeRequestId(persisted.selectedMergeRequestId)
  }
  setIsHydrated(true)
}, [])

useEffect(() => {
  if (!isHydrated) {
    return
  }
  window.sessionStorage.setItem(
    ONBOARDING_STORAGE_KEY,
    JSON.stringify({
      gitlabInstance,
      customInstance,
      token,
      projects,
      selectedProjectId,
      mergeRequests,
      selectedMergeRequestId,
    } satisfies OnboardingSessionState),
  )
}, [
  isHydrated,
  gitlabInstance,
  customInstance,
  token,
  projects,
  selectedProjectId,
  mergeRequests,
  selectedMergeRequestId,
])

useEffect(() => {
  if (!isHydrated) {
    return
  }
  if (routeStep !== "tokens") {
    return
  }
  if (startedEventTracked.current) {
    return
  }

  startedEventTracked.current = true
  void trackEvent("onboarding_started")
}, [isHydrated, routeStep])

useEffect(() => {
  setTokenTestFeedback(null)
}, [token, gitlabInstance, customInstance])

useEffect(() => {
  if (!isHydrated) {
    return
  }

  if (routeStep === "projects" && !token.trim()) {
    router.replace("/onboarding/tokens")
    return
  }

  if (routeStep === "mrs" && !selectedProjectId) {
    router.replace("/onboarding/projects")
  }
}, [isHydrated, routeStep, token, selectedProjectId, router])

useEffect(() => {
  if (!isHydrated || routeStep !== "projects" || actionBusy || recentProjects.length === 0) {
    return
  }

  const onKeyDown = (event: KeyboardEvent) => {
    if (
      event.defaultPrevented ||
      event.metaKey ||
      event.ctrlKey ||
      event.altKey ||
      event.repeat
    ) {
      return
    }

    const target = event.target as HTMLElement | null
    if (
      target &&
      (target.tagName === "INPUT" ||
        target.tagName === "TEXTAREA" ||
        target.tagName === "SELECT" ||
        target.isContentEditable)
    ) {
      return
    }

    if (!/^[0-9]$/.test(event.key)) {
      return
    }

    const index = event.key === "0" ? 9 : Number(event.key) - 1
    const project = recentProjects[index]
    if (!project) {
      return
    }

    event.preventDefault()
    void projectSelectionHandlerRef.current?.(project.id)
  }

  window.addEventListener("keydown", onKeyDown)
  return () => window.removeEventListener("keydown", onKeyDown)
}, [isHydrated, routeStep, actionBusy, recentProjects])

            {tokenTestFeedback ? (
              <p
                className={
                  tokenTestFeedback.kind === "error"
                    ? "text-xs text-destructive"
                    : "text-xs text-emerald-700"
                }
              >
                {tokenTestFeedback.message}
              </p>
            ) : null}
            {projectsError ? <p className="text-xs text-destructive">{projectsError}</p> : null}
            <div className="flex flex-col gap-2 sm:flex-row">
              <Button
                type="button"
                variant="outline"
                onClick={() => void testToken()}
                disabled={actionBusy || tokenTestBusy || !canLoadProjects}
              >
                {tokenTestBusy ? "Testing token..." : "Test token"}
              </Button>
              <Button
                type="submit"
                onMouseEnter={preloadProjectsForContinue}
                onFocus={preloadProjectsForContinue}
                onTouchStart={preloadProjectsForContinue}
                disabled={actionBusy || tokenTestBusy || !canLoadProjects}
              >
                {actionBusy ? "Loading projects..." : "Continue to projects"}
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  )
}

if (routeStep === "projects") {
  return (
    <div className="space-y-4">

{recentProjects.length > 0 ? (
  <div className="grid gap-2 sm:grid-cols-2">
    {recentProjects.map((project, index) => (
      <button
        key={project.id}
        type="button"
        onClick={() => void handleProjectSelection(project.id)}
